/**
 * 자유게시판 매일 자동 포스팅용 글 풀 — 상시성(evergreen) 글만 모아둔다.
 *
 * - post-daily-community.mjs 가 위에서부터 순서대로 하루 2~3건씩 올린다
 * - 특정 날짜·이벤트에 묶인 내용 금지 (언제 올라가도 어색하지 않아야 함)
 * - author/by: user 테이블의 name · content: 에디터가 저장하는 HTML 그대로
 * - views/likes 는 목표치 — 스크립트가 시간 경과에 따라 서서히 채운다
 * - 풀이 소진되면 크론이 실패 메일로 알려주므로, 여기에 글을 이어붙이면 된다
 */
import { IMAGES } from "./community-posts.mjs";
import { ALBUM_IMAGES } from "./goods-albums.mjs";

const p = (...lines) => lines.map((line) => (line === "" ? "<p><br></p>" : `<p>${line}</p>`)).join("");
const img = (src) => `<p><img src="${src}"></p>`;

//2026-11 리필용 — 공식 앨범 커버(iTunes 아트워크 1000px)를 게시판 버킷에 올려둔 것
const BOARD = "https://jzghadoanikvjvczuerw.supabase.co/storage/v1/object/public/boards/board";
const NEW = Object.fromEntries(
  [
    "lckEp", "lckSingle", "lckAlawn", "lckCaptain", "lckSpedUp", "lckInverness", "revivePlus", "bangBang", "empathy",
    "rebelHeart", "switchEp", "mineEp", "iveIve", "kitsch", "afterLike", "loveDive", "eleven", "iWant",
  ].map((key) => [key, `${BOARD}/pool-2611-${key}.jpg`])
);

//굿즈 버킷의 앨범 실물 사진 (굿즈샵 상품 이미지 재사용)
const GOODS = "https://jzghadoanikvjvczuerw.supabase.co/storage/v1/object/public/goods";
const SHOP = {
  mineAlbum: `${GOODS}/1-ep/album.webp`,
  mineList: `${GOODS}/1-ep/list.webp`,
  switchAlbum: `${GOODS}/2-ep/album.webp`,
  switchList1: `${GOODS}/2-ep/list-1.webp`,
  switchList2: `${GOODS}/2-ep/list-2.webp`,
  mini4Pink: `${GOODS}/4-mini-album/pink.webp`,
  mini4Blue: `${GOODS}/4-mini-album/blue.webp`,
  mini4Green: `${GOODS}/4-mini-album/green.webp`,
};

//간결 작성용 — q(제목, 작성자, 본문 줄[], 댓글[[by, text, [[by, text]]?]], 이미지?)
//이미지가 있으면 첫 줄 뒤에 붙인다 (p 안에 img를 넣으면 <p> 중첩). 조회수·좋아요는 제목 해시로 정한다
const hash = (s) => [...s].reduce((h, c) => (h * 31 + c.charCodeAt(0)) >>> 0, 7);
const q = (title, author, lines, comments = [], image) => {
  const h = hash(title);
  const [first, ...rest] = lines;
  const images = image ? [image].flat().map(img).join("") : "";
  return {
    title,
    author,
    views: 118 + (h % 73),
    likes: 5 + (h % 5),
    content: image ? p(first, "") + images + (rest.length ? p(...rest) : "") : p(...lines),
    comments: comments.map(([by, text, replies]) => ({
      by,
      text,
      ...(replies ? { replies: replies.map(([rb, rt]) => ({ by: rb, text: rt })) } : {}),
    })),
  };
};

